    assert.equal(await p.evaluate(()=>moneyLedger().entries.length),1);assert.equal(await p.evaluate(()=>LifeMoney.summary(moneyLedger(),getTodayKey(),'2026-10-31','villa').actualCents),620000);
    await p.evaluate(()=>openMoneyEntry('income'));await p.getByLabel('Entry name',{exact:true}).fill('Duplicate');await p.getByLabel('Amount (RM)',{exact:true}).fill('1200');await p.getByLabel('Status',{exact:true}).selectOption('planned');await p.getByLabel('Income source (optional)',{exact:true}).selectOption('Airbnb');await p.getByLabel('Expected / due date',{exact:true}).fill('2026-10-18');await p.getByLabel('Reservation / payment reference (optional)',{exact:true}).fill('TEST-BOOKING');await p.locator('#dailyDialog').getByRole('button',{name:'Save',exact:true}).click();assert.match(await p.locator('#dailyDialog [role=status]').innerText(),/already exists/);assert.equal(await p.evaluate(()=>moneyLedger().entries.length),1);
